# -*- coding: utf-8 -*-
"""Рядок 153 (1): модель LM Studio на жнивах — ознаки й слово кольору 40 речей. Набір — вибірка жнив v2 з фото в git
(`аудит/збагачення_v2_вибірка.json`, `аудит/фото_v2/`), сід 153: перші 4 речі кожної групи слота; той самий для всіх моделей
і не гниє разом з адресами крамниць. Промпт і розбір — самих жнив (`ПРОМПТ_НАБОРУ`, `_запит`, `нормалізувати`), один запит
полів на тому самому кадрі, що в записі v2 (запиту аркуша тут нема): ознаки — проти полів запису, колір — сім'я тону слова
моделі проти виміру v2 і проти слів крамниці. `--сам`: замість моделі — самі записи (мусить вийти 100 %, інакше rc 1).
`cd джерела && python проби/vymir_modelei_153.py <модель>`; (5) — vymir_foto_rechi_153.py, (3) — vymir_namiru_153.py. ТОЧКА ВІДЛІКУ 24.09: qwen3-vl-8b-instruct — ознаки 188/232 (колір: вимір v2 31/40) за 1.8 с/річ; два прогони збіглися до знака, бо жнива шлють `temperature: 0`. Кандидата міряти проти ЦИХ чисел, не проти 100 %. ЧИЙ ТУТ ЕТАЛОН (24.09, дивилась очима). `поля` — це відповіді САМОЇ qwen3-vl-8b з 18.09 (`мета.модель`), а не розсуд людини: «ознаки разом» кажуть, наскільки кандидат ЗГОДЕН з каталогом, який уже зібрано, а не наскільки він має рацію. На ж-01639 запис описує БІЛІ ДЖИНСИ, хоч річ — чорний лонгслів (слот «верх»), тож модель, яка відповість про лонгслів правильно, дістане нуль на всіх його полях. «Колір: вимір v2» теж не незалежний: `звести_колір` бере найбільший кластер У СІМ'Ї слова моделі (5 речей з 40 мають кластер на ≥0.2 менший за найбільший; очима 3 з тих 5 — правильні, 2 — ні). Єдиний цілком зовнішній лічильник тут — «колір: крамниця».
«ОЗНАКИ РАЗОМ» МОДЕЛІ НЕ РАНЖУЄ — виміряно на кандидаті 24.09, не здогад. gemma-4-12b-it-qat: ознаки 135/232 проти 188/232, але «колір: крамниця» 25/34 і «колір: вимір v2» 32/40 — обидва ЗОВНІШНІ лічильники ВИЩІ за поточну (24/34, 31/40). Сім дрібних полів, де qwen має рівно 4/4 (підошва, халява, фурнітура, розмір, метал, носок, масштаб), у gemma дають 1–3/4: це підпис автора каталогу, а не якість. Дивилась очима 4 речі з 14 розбіжними полями: КАТАЛОГ хибний на 6 (ж-01639 матеріал «денім» / довжина «максі» / крій «straight» описують БІЛІ ДЖИНСИ замість чорного лонгсліва в слоті; ж-05046 довжина «литка» на жакеті до стегна і «комір» на безкомірному; ж-04753 «комір» на халтері), КАНДИДАТ хибний на 2 (ж-10394 підошва «товста» на пласкій балетці; ж-04753 довжина «талія» замість «стегно»), решта 6 з фото не вирішуються (шкіра/екошкіра, вовна/вʼязане, fitted/bodycon). Тобто 81 % проти 58 % значить «вона своя», а не «вона краща», і міняти типову модель цим числом НЕ МОЖНА: рішення — за «колір: крамниця» і швидкістю. І ДРУГИЙ КАНДИДАТ ЦЕ ПІДТВЕРДИВ (24.09): Qwen3.5-9B Q8_0 без думання (`"reasoning_effort": "none"` — інакше `content` порожній, див. докстрінг (5)) дала ознаки 133/232 — тобто ще нижче за gemma, — але «колір: крамниця» 27/34, НАЙКРАЩИЙ із трьох (поточна 24, gemma 25), і «колір: вимір v2» 32/40. Знову: чим МЕНШЕ модель згодна з каталогом, який писала поточна, тим вище вона на зовнішніх еталонах. Ставати типовою їй заважає не якість, а ціна — 2.6 с/річ проти 1.8, це +44 % при стелі брифу +20 %, тобто 8.6 год на каталог замість 5.4. І ЦІ +3 Я ПЕРЕВІРИЛА ОКОМ, бо на них тримається все рішення: розбіжностей між поточною і Qwen3.5 рівно три, ВСІ на користь кандидатки, назад жодної. ж-05046 (верхній_шар, крамниця «синій») — на фото темно-синій вовняний жакет, кандидатка «синій», поточна «графіт»; ж-07734 (головний_убір, «коричневий») — темно-коричневий вовняний берет, кандидатка «коричневий», поточна «бежевий» (бежевим він не є ніяк); ж-07190 (низ, «блакитний/пудровий») — блакитні штани, кандидатка «блакитний», а поточна слова не дала ЗОВСІМ (None) — це мовчання, не хибний колір. Тобто 27/34 — справжня перевага, а не шум лічильника. І ЧЕТВЕРТИЙ ВИМІР ЗНІМАЄ ТЕ, ЩО ТРИМАЛО КАНДИДАТКУ: Qwen3.5-9B Q4_K_M — та сама модель, менший квант — дає ознаки 124/232, «колір: крамниця» 26/34, «колір: вимір v2» 32/40 і 1.9 с/річ проти 1.8 у поточної, тобто +6 % при стелі +20 %. Уперше кандидат вищий за поточну на ОБОХ зовнішніх лічильниках і ВСЕРЕДИНІ стелі часу: ціна, через яку Q8_0 (2.6 с/річ) не проходила, на Q4_K_M зникла, а 26 проти 27 у Q8_0 — НЕ втрата кольору: дивилась усі чотири розбіжності очима. Три влучання Q4_K_M дослівно ті самі, що в Q8_0 (ж-05046 «темно-синій», ж-07190 «блакитний», ж-07734 «коричневий»), а єдина «втрата» — ж-07624, слот «каблучка», крамниця «золотий»: КАБЛУЧКИ В КАДРІ НЕМА ЗОВСІМ. Там смарагдова в'язана сукня макі, золотий ланцюговий пасок і золотий браслет на зап'ясті; збільшувала обидві руки — на пальцях порожньо. Поточна й Q8_0 «влучили», назвавши золото ПАСКА, Q4_K_M «схибила», назвавши зелень СУКНІ, а про річ зі слота не відповів ніхто. Це та сама вада кадру, що й ж-01639, а не вада ока моделі. Число 26/34 повторилось двома окремими прогонами (проба і збирач слів) — жнива шлють t=0. Отже на кольорі Q4_K_M по суті рівна Q8_0, а коштує 1.9 с/річ замість 2.6, і типову модель тримає вже НЕ швидкість: каталог 10 770 описів зібрано поточною, кандидатка розходиться з ним на 108 полях з 232, тож заміна значить перезбирання (≈5.4 год) або мішаний каталог. Це рядок власникові, а не те, що вирішує вимір. MamayLM-Gemma-3-12B тут числа не має й не матиме: `lms ls --json` каже `vision: false`, mmproj у репозиторії нема, а ця проба шле фото — 0/232 було б про брак mmproj, а не про модель (її вимір — у докстрінгу (3)). ПЕРЕВІРЕНО 25.09 НА НОУТБУЦІ З ВІЛЬНОЮ GPU (рушій LM Studio 2.45.0 — оновлено того ранку о 07:38; усе вище міряно на 2.44.0) — І ЦЕ МІНЯЄ ВИСНОВОК АБЗАЦУ ВИЩЕ. (а) ОДИН ПРОГІН — НЕ ЧИСЛО. «Два прогони збіглися до знака» правда лише з того самого стану сервера (свіже завантаження, той самий порядок запитів); t=0 цього не рятує. Поточна за 7 прогонів (ця проба; той самий запит в 1 і в 3 потоки; 4 проходи трьома потоками) — ознаки 183–191, «колір: крамниця» 24–26, «вимір v2» 30–32; Q4_K_M за 7 — ознаки 120–124, колір рівно 26 і вимір рівно 32 щоразу. Тобто перевага кандидатки на кольорі цієї проби — 0–2, а не +2; порівнювати ДІАПАЗОНИ, не один прогін. Три потоки проти одного міняють 11–19 полів із 232 у кожної з трьох моделей, а жнива йдуть трьома. (б) ЦЯ ПРОБА МІРЯЄ ЛИШЕ ЗАПИТ ПОЛІВ НА ЗАДАНОМУ КАДРІ, а в жнивах кадр (аркуш 2×3) обирає та сама модель. Самі жнива (`жнива_v2.py --вибірка`, сід 17, 62 речі, 3 потоки, 0 збоїв в обох): основний колір запису в сім'ї слова крамниці — поточна 36/53, Q4_K_M 36/53, нарівно; інший кадр у 15 з 62; 5.44 проти 5.90 с/річ (+8.5 %; на 22 речах було +21–23 %). Два її гірші кадри видно оком (прогін на 22 речах): біла сукня rito — крупний план у тіні, названий «ціла_річ», дав «срібний»; срібний пояс morandi — образ на моделі, де пояс займає 0.3 % кадру, дав «чорний». (в) ПОЛЯ НА ЗАДАНОМУ КАДРІ — ОЧИМА: 112 полів на 38 речах, де каталог і Q4_K_M розходяться. Права кандидатка — 36, каталог — 26, обидва прийнятні — 14, фото не вирішує — 36 (з них 22 — формальність). Хибних значень у каталогу 36: найчастіше «комір» на безкомірних речах (6) і тканина, якої на фото нема (вельвет на гладкому пальті, атлас на замшевій на вигляд сукні, шкіра на паєтках). У кандидатки хибних значень 12, але ще 14 разів вона МОВЧИТЬ (null) там, де каталог правий: в'язане, вовну, замшу, льон, шовк на фото видно. Формальність у неї нижча на 2 у 20 з 22 спірних — заміна зсунула б шкалу всього каталогу. ОТЖЕ: у повному конвеєрі кандидатка нарівно на кольорі й повільніша; виграш — лише менше вигаданих ознак на заданому кадрі, ціною мовчання й зсуву формальності. Підстави міняти типову модель жнив вимір не дає; це рядок власнику, а не рішення проби."""
import collections, json, os, random, subprocess, sys, time, urllib.request
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import жнива_v2 as Ж, verify as V
мод, сам = next((a for a in sys.argv[1:] if not a.startswith("--")), "qwen3-vl-8b-instruct"), "--сам" in sys.argv
if not сам:
    try: urllib.request.urlopen("http://127.0.0.1:1234/v1/models", timeout=10)
    except Exception as e: sys.exit("LM Studio не відповідає (%s) — модель «%s» не виміряти" % (type(e).__name__, мод))
ТЕКА, гр, лік, збої = os.path.join(Ж.ТУТ, "аудит"), collections.defaultdict(list), collections.defaultdict(lambda: [0, 0]), collections.Counter()
for з in sorted(json.load(open(os.path.join(ТЕКА, "збагачення_v2_вибірка.json"), encoding="utf-8"))["речі"], key=lambda з: з["id"]):
    if з.get("поля") and os.path.exists(os.path.join(ТЕКА, з.get("фото_показу") or "-")): гр[Ж.група_слота(з["слот"])].append(з)
for г in гр: random.Random(153).shuffle(гр[г])
def рах(поле, так):
    """Лічильник «так / усього» на поле."""
    лік[поле][0] += bool(так); лік[поле][1] += 1
ЗВОРОТ, сім, нрм, т0 = {в: к for к, в in Ж.ДОВЖИНА_В_РІВЕНЬ.items()}, V.сім_я_слова, lambda v: sorted(v) if isinstance(v, list) else v, time.time()
речі = [з for г in sorted(гр) for з in гр[г][:4]]
for з in речі:
    п0, кр, вим = з["поля"], Ж.слова_крамниці(з.get("колір_крамниці") or ""), ((з.get("запис") or {}).get("колір_основний") or {}).get("слово")
    try: сире = dict(п0, колір_слово=п0.get("слово_моделі"), довжина=ЗВОРОТ.get(п0.get("довжина"), п0.get("довжина"))) if сам else Ж._запит(
            мод, Ж._підставити(Ж.ПРОМПТ_НАБОРУ[з["набір"]], з["тип"]), [Ж._b64(Ж._фото_1024(os.path.join(ТЕКА, з["фото_показу"])), сторона=1024)], токенів=600)
    except Exception as e: сире = {}; збої[type(e).__name__] += 1
    п = Ж.нормалізувати(сире, з["набір"])
    for к in п0:
        if к != "слово_моделі": рах(к, bool(сире) and нрм(п.get(к)) == нрм(п0[к]))   # збій — хибно на кожному полі, і на None теж
    if вим: рах("колір: вимір v2", сім(вим if сам else п.get("слово_моделі")) == сім(вим))
    if кр: рах("колір: крамниця", сім(кр[0] if сам else п.get("слово_моделі")) in {сім(с) for с in кр})
try: vram = subprocess.run(["nvidia-smi", "--query-gpu=memory.used,memory.total", "--format=csv,noheader"], capture_output=True, text=True, timeout=20).stdout.strip()
except Exception as e: vram = "nvidia-smi: " + type(e).__name__
озн = [в for к, в in лік.items() if not к.startswith("колір")]
print("(1) %d речей · модель %s%s · %.1f с/річ · збоїв %d%s · ознаки разом %d/%d · VRAM %s" % (len(речі), мод, " --сам (записи замість моделі)" if сам else "",
      (time.time() - т0) / len(речі), sum(збої.values()), " %s" % dict(збої) if збої else "", sum(в[0] for в in озн), sum(в[1] for в in озн), vram))
print("    " + " · ".join("%s %d/%d" % (к, *лік[к]) for к in sorted(лік)))
sys.exit(1 if сам and any(в[0] != в[1] for в in лік.values()) else 0)
